def carry_forward_existing_profiles(apps, schema_editor):
    Profile = apps.get_model('calc', 'Profile')
    RegionPortfolio = apps.get_model('calc', 'RegionPortfolio')
    for profile in Profile.objects.select_related('user'):
        update_fields = []
        if not profile.display_name:
            profile.display_name = profile.user.username
            update_fields.append('display_name')
        if profile.area == 'jeonnam' and not profile.primary_region:
            profile.primary_region = 'jeonnam'
            update_fields.append('primary_region')
            RegionPortfolio.objects.get_or_create(user=profile.user, region='jeonnam')
        if update_fields:
            profile.save(update_fields=update_fields)


